<?php

declare(strict_types=1);
require_once __DIR__.'/../../includes/cors.php';require_once __DIR__.'/../../includes/response.php';require_once __DIR__.'/../../includes/helpers.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/admin-audit.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false,'message'=>'Method not allowed'],405);$user=require_auth($pdo);require_role($user,['super_admin']);$input=get_json_input();$tenantId=filter_var($input['tenant_id']??0,FILTER_VALIDATE_INT,['options'=>['default'=>0,'min_range'=>1]]);$tagIds=array_values(array_unique(array_filter(array_map('intval',is_array($input['tag_ids']??null)?$input['tag_ids']:[]),static fn(int $id):bool=>$id>0)));if($tenantId<=0||count($tagIds)>30)json_response(['success'=>false,'message'=>'برچسب‌ها معتبر نیستند.'],422);
try{$tenant=$pdo->prepare('SELECT name FROM tenants WHERE id=:id');$tenant->execute([':id'=>$tenantId]);$name=$tenant->fetchColumn();if(!$name)json_response(['success'=>false,'message'=>'مشتری پیدا نشد.'],404);if($tagIds){$ph=implode(',',array_fill(0,count($tagIds),'?'));$check=$pdo->prepare("SELECT id FROM tenant_tags WHERE is_active=1 AND id IN ($ph)");$check->execute($tagIds);$valid=array_map('intval',$check->fetchAll(PDO::FETCH_COLUMN));sort($valid);$requested=$tagIds;sort($requested);if($valid!==$requested)json_response(['success'=>false,'message'=>'حداقل یکی از برچسب‌ها معتبر نیست.'],422);}
 $oldStmt=$pdo->prepare('SELECT tag_id FROM tenant_tag_assignments WHERE tenant_id=:id ORDER BY tag_id');$oldStmt->execute([':id'=>$tenantId]);$oldIds=array_map('intval',$oldStmt->fetchAll(PDO::FETCH_COLUMN));$pdo->beginTransaction();$pdo->prepare('DELETE FROM tenant_tag_assignments WHERE tenant_id=:id')->execute([':id'=>$tenantId]);$ins=$pdo->prepare('INSERT INTO tenant_tag_assignments(tenant_id,tag_id,assigned_by) VALUES(:tenant_id,:tag_id,:assigned_by)');foreach($tagIds as $tagId)$ins->execute([':tenant_id'=>$tenantId,':tag_id'=>$tagId,':assigned_by'=>(int)$user['id']]);$pdo->commit();admin_audit_log($pdo,$user,'customer.tags_updated','tenant',$tenantId,'برچسب‌های مشتری «'.$name.'» بروزرسانی شد.',['tag_ids'=>$oldIds],['tag_ids'=>$tagIds],['tenant_id'=>$tenantId]);json_response(['success'=>true,'message'=>'برچسب‌ها بروزرسانی شدند.']);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[CUSTOMER_TAGS_UPDATE] '.$e->getMessage());json_response(['success'=>false,'message'=>'بروزرسانی برچسب‌ها ناموفق بود.'],500);}
